// Config-driven MQTT normalizer.
// Default mappings cover common MQTT payloads. Override with EID_DEVICE_MAPPINGS_JSON.
// Mapping format:
// [{"topic":"tele/+/SENSOR","deviceId":"tasmota-${1}","deviceName":"Tasmota ${1}","deviceType":"tasmota","channels":[{"key":"el","path":"ENERGY.Total","scale":1}]}]

const topic = msg.topic || "";
const payload = msg.payload;
const allowRaw = (env.get("EID_DEVICE_ALLOWLIST") || "").trim();
const allowlist = allowRaw ? allowRaw.split(",").map(s => s.trim()).filter(Boolean) : [];
// Default 5000 points covers 1 Hz data buffered for over an hour, or 15 min intervals with margin.
const maxBufferPoints = parseInt(env.get("EID_MAX_BUFFER_POINTS") || "5000", 10);

const defaultMappings = [
    {
        topic: "tele/+/SENSOR",
        deviceId: "tasmota-${1}",
        deviceName: "Tasmota ${1}",
        deviceType: "tasmota",
        channels: [
            { key: "el", path: "ENERGY.Total", scale: 1 }
            // Optional examples the operator can enable in EID_DEVICE_MAPPINGS_JSON:
            // { key: "pwr", path: "ENERGY.Power", scale: 0.001 } // W -> kW
        ]
    },
    {
        topic: "shellies/+/relay/+/energy",
        deviceId: "shelly-${1}-r${2}",
        deviceName: "Shelly ${1} relay ${2}",
        deviceType: "shelly",
        channels: [
            { key: "el", path: "$payload", scale: 1 / 60000 } // watt-minutes -> kWh
        ]
    },
    {
        topic: "xky/+/tele/SENSOR",
        deviceId: "teleinfo-${1}",
        deviceName: "Teleinfo ${1}",
        deviceType: "teleinfo",
        channels: [
            { key: "pwr", path: "METER.W", scale: 0.001, optional: true },
            { key: "el", path: "CONTRACT.Conso", scale: 0.001, optional: true },
            { key: "el", path: "TIC.BASE", scale: 0.001, optional: true },
            { key: "el", path: "TIC.EAST", scale: 0.001, optional: true },
            { key: "el", paths: ["TIC.HCHC", "TIC.HCHP"], combine: "sum", scale: 0.001, optional: true },
            { key: "el", path: "BASE", scale: 0.001, optional: true },
            { key: "el", path: "EAST", scale: 0.001, optional: true },
            { key: "el", paths: ["HCHC", "HCHP"], combine: "sum", scale: 0.001, optional: true }
        ]
    }
];

function parseMappings() {
    const raw = (env.get("EID_DEVICE_MAPPINGS_JSON") || "").trim();
    if (!raw) return defaultMappings;
    try {
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) throw new Error("mapping root must be an array");
        return parsed;
    } catch (e) {
        node.warn(`Invalid EID_DEVICE_MAPPINGS_JSON, using defaults: ${e.message}`);
        return defaultMappings;
    }
}

function topicMatch(pattern, actual) {
    const pp = String(pattern || "").split("/");
    const aa = String(actual || "").split("/");
    const captures = [];
    for (let i = 0, j = 0; i < pp.length; i++, j++) {
        const p = pp[i];
        if (p === "#") return { ok: true, captures };
        if (j >= aa.length) return { ok: false };
        if (p === "+") { captures.push(aa[j]); continue; }
        if (p !== aa[j]) return { ok: false };
    }
    return { ok: pp.length === aa.length, captures };
}

function applyTemplate(template, captures) {
    return String(template || "").replace(/\$\{(\d+)\}/g, (_, n) => captures[Number(n) - 1] || "");
}

function getPath(obj, path) {
    if (path === "$payload") return obj;
    return String(path || "").split(".").reduce((acc, part) => {
        if (acc === null || acc === undefined) return undefined;
        return acc[part];
    }, obj);
}

function numeric(v) {
    if (typeof v === "number") return isFinite(v) ? v : null;
    if (typeof v === "string" && v.trim() !== "") {
        const n = Number(v);
        return isFinite(n) ? n : null;
    }
    return null;
}

function extractChannel(ch, payload) {
    let value = null;
    if (Array.isArray(ch.paths)) {
        const vals = ch.paths.map(p => numeric(getPath(payload, p))).filter(v => v !== null);
        if (vals.length === 0) return null;
        value = ch.combine === "sum" ? vals.reduce((a, b) => a + b, 0) : vals[0];
    } else {
        value = numeric(getPath(payload, ch.path));
    }
    if (value === null) return null;
    value = value * Number(ch.scale === undefined ? 1 : ch.scale) + Number(ch.offset || 0);
    if (ch.min !== undefined && value < Number(ch.min)) return null;
    if (ch.max !== undefined && value > Number(ch.max)) return null;
    return value;
}

function rememberUnmapped(reason) {
    const unmapped = global.get("eid.unmappedTopics") || {};
    const entry = unmapped[topic] || { topic, count: 0, firstSeenAt: Date.now() };
    entry.count++;
    entry.lastSeenAt = Date.now();
    entry.reason = reason;
    entry.sampleType = typeof payload;
    if (payload && typeof payload === "object") entry.sampleKeys = Object.keys(payload).slice(0, 20);
    unmapped[topic] = entry;
    global.set("eid.unmappedTopics", unmapped);
    node.status({ fill: "grey", shape: "ring", text: `${topic}: ${reason}` });
}

function allow(id) { return allowlist.length === 0 || allowlist.includes(id); }

const mappings = parseMappings();
let match = null;
for (const mapping of mappings) {
    const m = topicMatch(mapping.topic, topic);
    if (m.ok) { match = { mapping, captures: m.captures }; break; }
}

if (!match) { rememberUnmapped("no mapping"); return null; }

const mapping = match.mapping;
const captures = match.captures;
const deviceId = applyTemplate(mapping.deviceId, captures);
const deviceName = applyTemplate(mapping.deviceName || mapping.deviceId, captures);
const deviceType = mapping.deviceType || "mqtt";
if (!deviceId) { rememberUnmapped("mapping produced empty deviceId"); return null; }
if (!allow(deviceId)) return null;

const readings = {};
for (const ch of (mapping.channels || [])) {
    const key = ch.key;
    if (!key) continue;
    const value = extractChannel(ch, payload);
    if (value === null) continue;
    readings[key] = value;
}

if (Object.keys(readings).length === 0) {
    rememberUnmapped(`${deviceId}: no mapped values`);
    return null;
}

const registry = global.get("eid.registry") || {};
let entry = registry[deviceId];
if (!entry) {
    const cc = (mapping.claimCode ? applyTemplate(mapping.claimCode, captures) : deviceId.replace(/[^A-Za-z0-9]/g, "").slice(-6)).toUpperCase();
    entry = {
        deviceId, deviceType, deviceName,
        claimCode: cc,
        helloAttempts: 0,
        helloLastTriedAt: 0,
        webhookUrl: null,
        headers: null,
        recordName: null,
        recordNumber: null,
        claimUrl: null,
        claimed: false,
        discoveredAt: Date.now()
    };
    registry[deviceId] = entry;
    global.set("eid.registry", registry);
    node.warn(`Discovered ${deviceId} (claimCode=${cc})`);
}
entry.lastSeenAt = Date.now();
entry.lastTopic = topic;
entry.lastReadings = readings;
global.set("eid.registry", registry);

const buffers = global.get("eid.buffers") || {};
buffers[deviceId] = buffers[deviceId] || [];
buffers[deviceId].push(Object.assign({ ts: Math.floor(Date.now() / 1000) }, readings));
if (buffers[deviceId].length > maxBufferPoints) buffers[deviceId].splice(0, buffers[deviceId].length - maxBufferPoints);
global.set("eid.buffers", buffers);

const summary = Object.keys(readings).map(k => `${k}=${Number(readings[k]).toFixed(3)}`).join(", ");
node.status({
    fill: entry.claimed ? "green" : "yellow",
    shape: "dot",
    text: `${deviceId} ${summary} (buf ${buffers[deviceId].length}, claimed=${entry.claimed})`
});

msg.deviceId = deviceId;
msg.readings = readings;
msg.mapping = { topic: mapping.topic, deviceType };
return msg;

// /hello scheduler. Sends up to EID_HELLO_PER_TICK requests per tick (auto by default), in this order:
//  1) a forced refresh (re-auth after 401/403/404, or the "Refresh device connection" inject);
//  2) claimed devices whose credentials are due for a refresh (EID_CREDENTIAL_REFRESH_S, or 6 h before the
//     token in their headers expires), oldest refresh first. These go before unclaimed devices: with hundreds of
//     unclaimed devices the queue is never empty, and a refresh that waits behind it ends in a 401 later;
//  3) unclaimed devices, the one that waited longest first. A device that is still unclaimed after
//     EID_HELLO_IDLE_AFTER /hello calls slows down to EID_HELLO_IDLE_COOLDOWN_S (default 1800 s), inside the
//     60 min lifetime of an EnergyID registration request, so a fleet of unclaimed devices does not crowd out new ones.
function num(name, def) {
    const v = parseFloat(env.get(name));
    return isFinite(v) ? v : def;
}
const cooldown = num("EID_HELLO_COOLDOWN_S", 300) * 1000;
const idleCooldown = Math.max(cooldown, num("EID_HELLO_IDLE_COOLDOWN_S", 1800) * 1000);
const idleAfter = num("EID_HELLO_IDLE_AFTER", 12);
const refreshEvery = num("EID_CREDENTIAL_REFRESH_S", 86400) * 1000;
const httpTimeout = num("EID_HTTP_TIMEOUT_S", 30) * 1000;
const EXPIRY_MARGIN = 6 * 3600 * 1000;
const now = Date.now();
const registry = global.get("eid.registry") || {};

function isForcedDeviceId(v) {
    return typeof v === "string" && v.trim().length > 0 && registry[v.trim()];
}

const picks = [];
const forcedId = isForcedDeviceId(msg.refreshDeviceId) ? msg.refreshDeviceId.trim()
    : isForcedDeviceId(msg.payload) ? msg.payload.trim()
    : null;

if (forcedId) {
    picks.push({ d: registry[forcedId], reason: "forced-refresh" });
} else {
    const refresh = [];
    const claim = [];
    for (const k of Object.keys(registry)) {
        const d = registry[k];
        if (!d) continue;
        const last = d.helloLastTriedAt || 0;
        if (d.helloNextAt && now < d.helloNextAt) continue; // backoff set by the store node (409, 5xx)
        if (d.claimed) {
            if ((now - last) < cooldown) continue;
            const lastRefresh = d.connectionRefreshedAt || d.claimedAt || d.discoveredAt || 0;
            const expiring = d.credentialExpiresAt && now > d.credentialExpiresAt - EXPIRY_MARGIN;
            if (!expiring && (now - lastRefresh) < refreshEvery) continue;
            refresh.push({ d, key: lastRefresh, reason: expiring ? "expiring-refresh" : "scheduled-refresh" });
        } else {
            const wait = (d.helloAttempts || 0) >= idleAfter ? idleCooldown : cooldown;
            if ((now - last) < wait) continue;
            claim.push({ d, key: last, reason: "claim" });
        }
    }
    refresh.sort((a, b) => a.key - b.key);
    claim.sort((a, b) => a.key - b.key);
    // Unset ("auto"): enough to work through the due list in about 5 min (60 ticks), between 2 and 10 per tick.
    // After a Node-RED restart without persistent context every device needs a /hello; 2 per tick would leave a
    // 2000-device fleet partly offline for 80 min, 10 per tick takes 17 min.
    const due = refresh.length + claim.length;
    const perTick = Math.max(1, Math.floor(num("EID_HELLO_PER_TICK", Math.min(10, Math.max(2, Math.ceil(due / 60))))));
    for (const p of refresh.concat(claim)) {
        if (picks.length >= perTick) break;
        picks.push(p);
    }
}

if (picks.length === 0) {
    node.status({ fill: "grey", shape: "ring", text: "queue idle" });
    return null;
}

for (const { d, reason } of picks) {
    d.helloAttempts = (d.helloAttempts || 0) + 1;
    d.helloLastTriedAt = now;
    node.send({
        deviceId: d.deviceId,
        helloReason: reason,
        url: "https://hooks.energyid.eu/hello",
        method: "POST",
        requestTimeout: httpTimeout,
        headers: {
            "Content-Type": "application/json",
            "X-Provisioning-Key": env.get("ENERGYID_PROVISIONING_KEY"),
            "X-Provisioning-Secret": env.get("ENERGYID_PROVISIONING_SECRET")
        },
        payload: {
            deviceId: d.deviceId,
            deviceName: d.deviceName,
            claimCode: d.claimCode
        }
    });
}
global.set("eid.registry", registry);
const first = picks[0];
node.status({ fill: "blue", shape: "dot", text: `${picks.length} /hello: ${first.reason} ${first.d.deviceId}${picks.length > 1 ? " +" + (picks.length - 1) : ""}` });
return null;

const status = msg.statusCode;
let body = msg.payload || {};
if (typeof body === "string") {
    try { body = JSON.parse(body); } catch (e) { body = { raw: body }; }
}
const registry = global.get("eid.registry") || {};
const dev = registry[msg.deviceId];
if (!dev) return null;

// Expiry of the credentials in the returned headers: "Bearer <jwt>" (exp claim) for /webhook-in,
// "SharedAccessSignature ...&se=<unix>&..." for Service Bus. null when it cannot be read.
function credentialExpiry(headers) {
    const auth = headers && (headers.authorization || headers.Authorization);
    if (typeof auth !== "string") return null;
    const se = /[?&\s]se=(\d+)/.exec(" " + auth.replace(/^SharedAccessSignature\s+/i, "&"));
    if (se) return Number(se[1]) * 1000;
    const m = /^Bearer\s+[^.]+\.([^.]+)\./i.exec(auth);
    if (m) {
        try {
            const claims = JSON.parse(Buffer.from(m[1].replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8"));
            if (claims && claims.exp) return Number(claims.exp) * 1000;
        } catch (e) { /* not a JWT */ }
    }
    return null;
}

if (status !== 200 && status !== 201) {
    dev.connectionRefreshError = `HTTP ${status || "no response"}`;
    if (status === 409 && body.error === "claim_code_in_use") {
        // Another device already holds this claimCode: retrying at the normal cadence cannot help, so back off.
        const holder = body.deviceId || "unknown";
        dev.helloError = `claim_code_in_use (held by ${holder})`;
        dev.helloNextAt = Date.now() + 30 * 60 * 1000;
        global.set("eid.registry", registry);
        node.warn(`/hello ${msg.deviceId}: claimCode ${body.claimCode || dev.claimCode} is already in use by device ${holder}; retry in 30 min. Give one of the two devices a different claimCode.`);
        node.status({ fill: "red", shape: "ring", text: `409 ${msg.deviceId}: code ${body.claimCode || dev.claimCode} used by ${holder}` });
        msg.outcome = `HTTP 409 claim_code_in_use (held by ${holder})`;
        return msg;
    }
    // 429/5xx/no response: EnergyID is busy or unreachable; do not hammer it, try this device again in 5 min.
    if (!status || status === 429 || status >= 500) dev.helloNextAt = Date.now() + 5 * 60 * 1000;
    dev.helloError = `HTTP ${status || "no response"}`;
    global.set("eid.registry", registry);
    node.warn(`/hello ${msg.deviceId} -> HTTP ${status}: ${JSON.stringify(body).slice(0, 200)}`);
    msg.outcome = `HTTP ${status}`;
    return msg;
}

dev.helloError = null;
dev.helloNextAt = 0;

if (body.webhookUrl && body.headers) {
    const endpoint = String(body.webhookUrl).includes("servicebus") ? "servicebus" : "webhook";
    if (dev.endpoint && dev.endpoint !== endpoint) node.warn(`${msg.deviceId}: upload endpoint changed ${dev.endpoint} -> ${endpoint}`);
    dev.webhookUrl     = body.webhookUrl;
    dev.headers        = body.headers;
    dev.endpoint       = endpoint;
    dev.recordName     = body.recordName;
    dev.recordNumber   = body.recordNumber;
    dev.uploadInterval = Number((body.webhookPolicy && body.webhookPolicy.uploadInterval) || 60);
    dev.credentialExpiresAt = credentialExpiry(body.headers);
    dev.claimed        = true;
    dev.claimedAt      = dev.claimedAt || Date.now();
    dev.connectionRefreshedAt = Date.now();
    dev.connectionRefreshError = null;
    if (!dev.nextUploadAfter || dev.nextUploadAfter > Date.now() + dev.uploadInterval * 1000) dev.nextUploadAfter = 0;
    global.set("eid.registry", registry);
    node.status({ fill: "green", shape: "dot", text: `${endpoint} ${msg.deviceId} ${dev.uploadInterval}s` });
    msg.outcome = `${msg.helloReason || "hello"} -> ${endpoint} ${dev.uploadInterval}s ${body.recordName}`;
    return msg;
}

if (body.claimUrl || body.claimCode) {
    dev.claimUrl  = body.claimUrl  || dev.claimUrl;
    dev.claimCode = body.claimCode || dev.claimCode;
    dev.claimed = false;
    dev.webhookUrl = null;
    dev.headers = null;
    dev.endpoint = null;
    dev.credentialExpiresAt = null;
    dev.connectionRefreshedAt = null;
    dev.connectionRefreshError = null;
    global.set("eid.registry", registry);
    node.status({ fill: "yellow", shape: "ring", text: `pending ${msg.deviceId} (${dev.claimCode})` });
    msg.outcome = `pending claim ${dev.claimCode}`;
    return msg;
}

global.set("eid.registry", registry);
node.warn(`/hello ${msg.deviceId}: unexpected body ${JSON.stringify(body).slice(0, 200)}`);
msg.outcome = "unexpected";
return msg;

// Upload scheduler, runs every 10 s. One POST carries one device's buffered readings (an EnergyID webhook URL and its
// credentials belong to one device), so scaling to many devices is about spending requests well:
//  - compaction: readings closer together than EID_MIN_POINT_SPACING_S (default 60 s) are merged, keeping the latest
//    value of each key. EnergyID resamples to the record interval anyway; 1-25 s samples only cost requests and bytes.
//  - fairness: of the devices that are due, the one whose last upload is oldest goes first, so a limited request budget
//    rotates over the whole fleet instead of always serving the same devices.
//  - a global cap: at most EID_MAX_INFLIGHT requests in flight and EID_MAX_SENDS_PER_TICK new ones per tick (auto by default).
//  - per-host pause: after a 429 the whole host (e.g. hooks.energyid.eu) is paused (see the response node), since its
//    limit counts requests per caller IP, not per device.
//  - big batches: up to EID_MAX_BATCH_SIZE points and EID_MAX_BATCH_BYTES of JSON per request; a device with a backlog
//    is due again after EID_BACKLOG_INTERVAL_S instead of its full upload interval.
function num(name, def) {
    const v = parseFloat(env.get(name));
    return isFinite(v) ? v : def;
}
const registry = global.get("eid.registry") || {};
const buffers  = global.get("eid.buffers")  || {};
const hosts    = global.get("eid.hosts")    || {};
const now = Date.now();
const maxBatchSize = num("EID_MAX_BATCH_SIZE", 1000);
const maxBatchBytes = num("EID_MAX_BATCH_BYTES", 200000);
const maxBufferPoints = num("EID_MAX_BUFFER_POINTS", 5000);
const spacingS = num("EID_MIN_POINT_SPACING_S", 60);
const backlogS = Math.max(10, num("EID_BACKLOG_INTERVAL_S", 60));
// A response can be lost (deploy/restart while the request was in flight, hung socket): after this long the batch is put back.
const inflightTimeout = num("EID_INFLIGHT_TIMEOUT_S", 120) * 1000;
const httpTimeout = num("EID_HTTP_TIMEOUT_S", 30) * 1000;

function hostOf(url) {
    const m = /^https?:\/\/([^/:]+)/i.exec(String(url || ""));
    return m ? m[1].toLowerCase() : "";
}

// Merge points that fall in the same spacing bucket; later values win, keys missing later are kept.
// Only the part after index `from` (already compacted before) is rewritten, in place.
function compact(buf, from) {
    if (spacingS <= 0 || buf.length < 2) return;
    let w = Math.max(0, Math.min(from, buf.length - 1));
    let lastBucket = Math.floor(Number(buf[w].ts) / spacingS);
    for (let r = w + 1; r < buf.length; r++) {
        const p = buf[r];
        const bucket = Math.floor(Number(p.ts) / spacingS);
        if (bucket === lastBucket) buf[w] = Object.assign({}, buf[w], p);
        else { buf[++w] = p; lastBucket = bucket; }
    }
    buf.length = w + 1;
}

let inflight = 0;
let recovered = 0;
let paused = 0;
const due = [];
for (const k of Object.keys(registry)) {
    const d = registry[k];
    if (!d) continue;
    if (d.inflight) {
        const startedAt = Number(d.inflight.startedAt || 0);
        if ((now - startedAt) < inflightTimeout) { inflight++; continue; }
        // Stale in-flight batch: restore the points at the front of the buffer and clear the flag.
        const lost = Array.isArray(d.inflight.batch) ? d.inflight.batch : [];
        buffers[k] = lost.concat(buffers[k] || []).slice(-maxBufferPoints);
        delete d.inflight;
        d.failureCount = (d.failureCount || 0) + 1;
        d.lastUploadError = "inflight timeout";
        d.nextUploadAfter = now;
        recovered++;
        node.warn(`${k}: in-flight batch stuck for ${Math.round((now - startedAt) / 1000)}s, requeued ${lost.length} points`);
    }
    const buf = buffers[k];
    if (!buf || buf.length === 0) continue;
    if (buf.length !== d.compactedLength || buf[0].ts !== d.compactedHeadTs) {
        // Only the new tail needs merging when points were appended (same head, longer buffer); a requeue at the
        // front or a trim by the router changes the head and recompacts the whole buffer.
        const appended = buf[0].ts === d.compactedHeadTs && buf.length > (d.compactedLength || 0);
        compact(buf, appended ? d.compactedLength - 1 : 0);
        d.compactedLength = buf.length;
        d.compactedHeadTs = buf[0].ts;
    }
    if (!d.claimed || !d.webhookUrl || !d.headers) continue;
    if (now < Number(d.nextUploadAfter || 0)) continue;
    const host = hostOf(d.webhookUrl);
    if (hosts[host] && now < Number(hosts[host].pausedUntil || 0)) { paused++; continue; }
    due.push({ k, d, host, waitingSince: d.lastUploadAt || d.claimedAt || 0 });
}

due.sort((a, b) => a.waitingSince - b.waitingSince);

// Request caps. Unset ("auto"): twice the steady-state rate of the claimed fleet (sum of 10 s / upload interval),
// at least 8, so a growing fleet never needs tuning while a backlog still drains gradually instead of in one burst.
let steadyPerTick = 0;
for (const k of Object.keys(registry)) {
    const d = registry[k];
    if (d && d.claimed) steadyPerTick += 10 / Math.max(60, Number(d.uploadInterval || 60));
}
const autoCap = Math.max(8, Math.ceil(2 * steadyPerTick));
const maxInflight = Math.max(1, num("EID_MAX_INFLIGHT", autoCap));
const maxPerTick = Math.max(1, num("EID_MAX_SENDS_PER_TICK", autoCap));

let sent = 0;
const slots = Math.min(maxPerTick, maxInflight - inflight);
for (const { k, d } of due) {
    if (sent >= slots) break;
    const buf = buffers[k];
    // Size the batch: count limit, per-device limit after a 400/413 split, and a JSON byte limit (Service Bus: 256 KB).
    const limit = Math.max(1, Math.min(maxBatchSize, Number(d.batchLimit || maxBatchSize)));
    let n = Math.min(limit, buf.length);
    let bytes = 2;
    for (let i = 0; i < n; i++) {
        bytes += JSON.stringify(buf[i]).length + 1;
        if (bytes > maxBatchBytes && i > 0) { n = i; break; }
    }
    const batch = buf.splice(0, n);
    d.compactedLength = buf.length;
    d.compactedHeadTs = buf.length ? buf[0].ts : null;
    d.inflight = { batch, startedAt: now };
    const intervalS = Math.max(60, Number(d.uploadInterval || 60));
    d.nextUploadAfter = now + (buf.length > 0 ? Math.min(backlogS, intervalS) : intervalS) * 1000;

    node.send({
        deviceId: k,
        batchStartedAt: now,
        url: d.webhookUrl,
        method: "POST",
        requestTimeout: httpTimeout,
        headers: Object.assign({}, d.headers, { "Content-Type": "application/json" }),
        payload: batch
    });
    sent++;
}

global.set("eid.registry", registry);
global.set("eid.buffers", buffers);
const waiting = due.length - sent;
node.status({
    fill: sent ? "blue" : (recovered ? "yellow" : "grey"),
    shape: sent ? "dot" : "ring",
    text: `sent ${sent}, in flight ${inflight + sent}, due ${waiting}` + (paused ? `, ${paused} on paused host` : "") + (recovered ? `, recovered ${recovered}` : "")
});
return null;

// Input comes from the http request node (any status code, since "senderr" is off) or from the Catch node
// (network error / timeout: no numeric statusCode, msg.error set). code 0 means "no HTTP response".
// Output 1: debug. Output 2: debug + re-auth link to the /hello queue (401/403/404 only).
function num(name, def) {
    const v = parseFloat(env.get(name));
    return isFinite(v) ? v : def;
}
const code = typeof msg.statusCode === "number" ? msg.statusCode : 0;
const id   = msg.deviceId;
const registry = global.get("eid.registry") || {};
const buffers  = global.get("eid.buffers")  || {};
const hosts    = global.get("eid.hosts")    || {};
const maxBufferPoints = num("EID_MAX_BUFFER_POINTS", 5000);
const hostPauseMaxS = num("EID_HOST_PAUSE_MAX_S", 900);
const now = Date.now();
const d = registry[id];
const inflight = d && d.inflight;

// No matching in-flight batch: either the scheduler already requeued it (late response), or this is the second
// copy of a network error (Node-RED sends it on the output and to the Catch node). Ignore either way.
if (d && (!inflight || (msg.batchStartedAt && inflight.startedAt !== msg.batchStartedAt))) {
    if (code) node.warn(`${id}: ignoring late response (HTTP ${code}) for a batch that is no longer in flight`);
    return null;
}

const batch = inflight && Array.isArray(inflight.batch) ? inflight.batch : [];
const errText = code ? `HTTP ${code}` : `network error: ${(msg.error && msg.error.message) || msg.statusCode || "no response"}`;
const hostMatch = /^https?:\/\/([^/:]+)/i.exec(String((d && d.webhookUrl) || msg.url || msg.responseUrl || ""));
const host = hostMatch ? hostMatch[1].toLowerCase() : "";
const hs = hosts[host] = hosts[host] || { ok: 0, throttled: 0, errors: 0, pauses: 0 };

msg.result = { deviceId: id, statusCode: code, body: msg.payload, sentCount: batch.length };

if (d) delete d.inflight;

function requeue(points) {
    if (!points.length) return;
    buffers[id] = points.concat(buffers[id] || []).slice(-maxBufferPoints);
}

function save() {
    global.set("eid.registry", registry);
    global.set("eid.buffers", buffers);
    global.set("eid.hosts", hosts);
}

if (code >= 200 && code < 300) {
    if (d) {
        d.lastUploadAt = now;
        d.lastUploadPoints = batch.length;
        d.failureCount = 0;
        d.lastUploadError = null;
        // After a 400/413 split, grow the batch again step by step.
        if (d.batchLimit) d.batchLimit = d.batchLimit * 2 >= num("EID_MAX_BATCH_SIZE", 1000) ? null : d.batchLimit * 2;
    }
    hs.ok++;
    hs.lastOkAt = now;
    hs.consecutive429 = 0;
    save();
    node.status({ fill: "green", shape: "dot", text: `OK ${id} (${code}, ${batch.length})` });
    return [msg, null];
}

if (d) {
    d.failureCount = (d.failureCount || 0) + 1;
    d.lastUploadError = errText;
    d.lastUploadErrorAt = now;
}

// 401/403/404: credentials expired or the integration was removed. Drop the connection and force a /hello
// for this device right away; it returns fresh credentials, or a claim code if the device is no longer claimed.
if ((code === 401 || code === 403 || code === 404) && d) {
    requeue(batch);
    d.claimed = false;
    d.webhookUrl = null;
    d.headers = null;
    d.endpoint = null;
    d.credentialExpiresAt = null;
    d.helloAttempts = 0;
    d.helloLastTriedAt = 0;
    d.helloNextAt = 0;
    d.connectionRefreshedAt = null;
    d.nextUploadAfter = 0;
    hs.errors++;
    save();
    node.warn(`${code} ${id} - re-auth queued, requeued ${batch.length}`);
    node.status({ fill: "yellow", shape: "ring", text: `re-auth ${id} (${code})` });
    return [null, { refreshDeviceId: id, payload: id, result: msg.result }];
}

// 400/413/422: EnergyID refuses this batch. Resending the same batch forever would block the device, so split it:
// halve the batch size and retry; a single point that is still refused is dropped and counted.
if ((code === 400 || code === 413 || code === 422) && d) {
    hs.errors++;
    if (batch.length > 1) {
        requeue(batch);
        d.batchLimit = Math.max(1, Math.floor(batch.length / 2));
        d.nextUploadAfter = now + 10 * 1000;
        node.warn(`${errText} ${id}: batch of ${batch.length} refused, retrying in batches of ${d.batchLimit}: ${JSON.stringify(msg.payload).slice(0, 200)}`);
    } else {
        d.droppedPoints = (d.droppedPoints || 0) + batch.length;
        d.lastDroppedPoint = batch[0] || null;
        d.nextUploadAfter = now + 10 * 1000;
        node.warn(`${errText} ${id}: dropped point ${JSON.stringify(batch[0])}: ${JSON.stringify(msg.payload).slice(0, 200)}`);
    }
    save();
    node.status({ fill: "red", shape: "ring", text: `${errText} ${id}` });
    return [msg, null];
}

requeue(batch);

if (code === 429 || code === 503) {
    // The limit is per caller (IP) on the host, not per device: pause the whole host. Honour Retry-After (seconds,
    // may be fractional) but cap a single pause; consecutive 429s double the pause, a success resets it.
    const h = (msg.headers && (msg.headers["retry-after"] || msg.headers["Retry-After"])) || "";
    const retryAfterS = parseFloat(h);
    hs.consecutive429 = (hs.consecutive429 || 0) + 1;
    const stepS = Math.min(hostPauseMaxS, 30 * Math.pow(2, hs.consecutive429 - 1));
    const pauseS = isFinite(retryAfterS) && retryAfterS > 0 ? Math.min(retryAfterS, stepS) : stepS;
    hs.pausedUntil = Math.max(Number(hs.pausedUntil || 0), now + pauseS * 1000);
    hs.throttled++;
    hs.pauses++;
    hs.last429At = now;
    if (d) d.nextUploadAfter = hs.pausedUntil;
    save();
    node.warn(`${errText} ${id}; requeued ${batch.length}, ${host} paused ${Math.round(pauseS)} s`);
    node.status({ fill: "red", shape: "ring", text: `${errText} ${id}, ${host} paused ${Math.round(pauseS)} s` });
    return [msg, null];
}

// Other errors (5xx, network, timeout): back off this device exponentially, 1 min doubling up to 15 min.
hs.errors++;
if (d) d.nextUploadAfter = now + Math.min(900, 60 * Math.pow(2, Math.min(4, (d.failureCount || 1) - 1))) * 1000;
save();
// Do not log msg.payload for network errors: it contains the request URL.
const detail = code ? JSON.stringify(msg.payload).slice(0, 200) : "";
node.warn(`${errText} ${id}${detail ? ": " + detail : ""}; requeued ${batch.length}`);
node.status({ fill: "red", shape: "ring", text: `${errText} ${id}` });
return [msg, null];

const r = global.get("eid.registry") || {};
const b = global.get("eid.buffers")  || {};
const hosts = global.get("eid.hosts") || {};
const now = Date.now();
const cooldownS = parseInt(env.get("EID_HELLO_COOLDOWN_S") || "300", 10);
const idleCooldownS = Math.max(cooldownS, parseInt(env.get("EID_HELLO_IDLE_COOLDOWN_S") || "1800", 10));
const inflightTimeoutS = parseInt(env.get("EID_INFLIGHT_TIMEOUT_S") || "120", 10);
const iso = ms => ms ? new Date(ms).toISOString() : "";
const ageMin = ms => ms ? Math.round((now - ms) / 60000) : null;
const endpointOf = d => d.endpoint || (d.webhookUrl ? (d.webhookUrl.includes("servicebus") ? "servicebus" : "webhook") : "");

const rows = Object.values(r).map(d => ({
    deviceId:   d.deviceId,
    type:       d.deviceType,
    claimed:    d.claimed,
    claimCode:  d.claimCode,
    recordName: d.recordName || "",
    recordNumber: d.recordNumber || "",
    endpoint:   endpointOf(d),
    uploadInterval: d.uploadInterval || "",
    attempts:   d.helloAttempts,
    buffered:   (b[d.deviceId] || []).length,
    oldestBufferedAt: (b[d.deviceId] || []).length ? iso(Number(b[d.deviceId][0].ts) * 1000) : "",
    lastSeenAt:   iso(d.lastSeenAt),
    lastHelloAt:  iso(d.helloLastTriedAt),
    lastUploadAt: iso(d.lastUploadAt),
    credentialExpiresAt: iso(d.credentialExpiresAt),
    inflightAgeS: d.inflight ? Math.round((now - Number(d.inflight.startedAt || 0)) / 1000) : null,
    helloError:   d.helloError || d.connectionRefreshError || "",
    uploadError:  d.lastUploadError || "",
    failureCount: d.failureCount || 0,
    droppedPoints: d.droppedPoints || 0,
    lastTopic:  d.lastTopic || "",
    lastReadings: d.lastReadings || {},
    claimUrl:   d.claimUrl || ""
}));

// Things worth looking at, one line each. Empty list = healthy.
const problems = [];
for (const d of Object.values(r)) {
    const id = d.deviceId;
    const buffered = (b[id] || []).length;
    const intervalS = Math.max(60, Number(d.uploadInterval || 60));
    if (d.lastSeenAt && ageMin(d.lastSeenAt) > 60) problems.push(`${id}: no MQTT data for ${ageMin(d.lastSeenAt)} min`);
    if (d.helloError) problems.push(`${id}: /hello ${d.helloError}`);
    if (d.claimed) {
        if (d.inflight && (now - Number(d.inflight.startedAt || 0)) > inflightTimeoutS * 1000) problems.push(`${id}: batch in flight for ${Math.round((now - d.inflight.startedAt) / 1000)} s`);
        if (d.lastUploadError) problems.push(`${id}: last upload failed (${d.lastUploadError}), ${d.failureCount || 0} failures in a row`);
        if (buffered > 0 && (!d.lastUploadAt || (now - d.lastUploadAt) > 3 * intervalS * 1000)) problems.push(`${id}: ${buffered} points buffered, last upload ${d.lastUploadAt ? ageMin(d.lastUploadAt) + " min ago" : "never"}`);
        if (d.droppedPoints) problems.push(`${id}: ${d.droppedPoints} points refused by EnergyID and dropped (last: ${JSON.stringify(d.lastDroppedPoint)})`);
    } else if (!d.helloLastTriedAt || (now - d.helloLastTriedAt) > 3 * idleCooldownS * 1000) {
        problems.push(`${id}: unclaimed, no /hello for ${d.helloLastTriedAt ? ageMin(d.helloLastTriedAt) + " min" : "ever"}`);
    }
}

const claimed   = rows.filter(x => x.claimed);
const unclaimed = rows.filter(x => !x.claimed);
const byEndpoint = {};
for (const x of claimed) byEndpoint[x.endpoint || "none"] = (byEndpoint[x.endpoint || "none"] || 0) + 1;
// /webhook-in counts requests per caller IP; many devices behind one bridge share that budget.
if ((byEndpoint.webhook || 0) > 25) {
    problems.unshift(`fleet: ${byEndpoint.webhook} devices upload to /webhook-in, which EnergyID rate-limits per caller IP; ask EnergyID to route this provisioning key to Service Bus`);
}
for (const [h, s] of Object.entries(hosts)) {
    if (s.pausedUntil && now < s.pausedUntil) problems.unshift(`host ${h}: paused for ${Math.round((s.pausedUntil - now) / 1000)} s after HTTP 429/503 (${s.throttled || 0} throttled, ${s.ok || 0} ok since start)`);
}
const sinceUpload = claimed.map(x => x.lastUploadAt ? (now - Date.parse(x.lastUploadAt)) / 60000 : Infinity).sort((a, c) => a - c);
const pct = p => sinceUpload.length ? Math.round(sinceUpload[Math.min(sinceUpload.length - 1, Math.floor(p * sinceUpload.length))]) : null;

msg.payload = {
    total: rows.length,
    claimedCount: claimed.length,
    unclaimedCount: unclaimed.length,
    endpoints: byEndpoint,
    bufferedPoints: rows.reduce((s, x) => s + x.buffered, 0),
    minutesSinceLastUpload: { p50: pct(0.5), p95: pct(0.95), max: pct(0.999999) },
    hosts,
    problems,
    claimed,
    unclaimed,
    all: rows
};
node.status({ fill: problems.length ? "yellow" : "green", shape: "dot", text: `${claimed.length} claimed (${Object.entries(byEndpoint).map(([k, v]) => k + " " + v).join(", ")}), ${unclaimed.length} unclaimed, ${problems.length} problems` });
return msg;

const r = global.get("eid.registry") || {};
const rows = Object.values(r).filter(d => !d.claimed);
const header = "deviceId,deviceType,claimCode,claimUrl";
const body = rows.map(d => `${d.deviceId},${d.deviceType},${d.claimCode},${d.claimUrl||""}`).join("\n");
msg.payload = header + "\n" + body + "\n";
msg.filename = "mqtt-bridge-unclaimed-" + new Date().toISOString().slice(0,10) + ".csv";
return msg;

global.set("eid.registry", {});
global.set("eid.buffers", {});
msg.payload = "registry + buffers cleared";
node.warn("MQTT bridge: registry and buffers wiped");
return msg;

const u = global.get("eid.unmappedTopics") || {};
const rows = Object.values(u).sort((a, b) => (b.lastSeenAt || 0) - (a.lastSeenAt || 0));
msg.payload = {
    total: rows.length,
    rows
};
return msg;

global.set("eid.unmappedTopics", {});
msg.payload = "unmapped topic list cleared";
return msg;
